-- CTEs para obtener IDs de subcategorías una sola vez
WITH
  sub_ambiental AS (
    SELECT s.id AS sub_id, s.categoria_id AS cat_id
    FROM subcategorias s WHERE lower(s.slug) = 'aromatizantes-ambientales' LIMIT 1
  ),
  sub_difusores AS (
    SELECT s.id AS sub_id, s.categoria_id AS cat_id
    FROM subcategorias s WHERE lower(s.slug) = 'difusores' LIMIT 1
  ),
  sub_ropa AS (
    SELECT s.id AS sub_id, s.categoria_id AS cat_id
    FROM subcategorias s WHERE lower(s.slug) = 'ropa' LIMIT 1
  ),
  sub_esenciales AS (
    SELECT s.id AS sub_id, s.categoria_id AS cat_id
    FROM subcategorias s WHERE lower(s.slug) = 'esenciales' LIMIT 1
  )

